let COLLON = pref("iv-colllinks", true) !== false;
const CIDX = new Map(); N.forEach((d, i) => { if (d.archive) return; const k_ = String(d.title).toLowerCase(); if (!CIDX.has(k_)) CIDX.set(k_, i); });
